class SplayTree:
    def right_rotate(self, x: SplayNode) -> SplayNode:
        y = x.left
        x.left = y.right
        y.right = x
        return y

    def left_rotate(self, x: SplayNode) -> SplayNode:
        y = x.right
        x.right = y.left
        y.left = x
        return y

    def splay(self, root: SplayNode, key: int) -> SplayNode:
        if not root or root.key == key: return root

        if key < root.key:
            if not root.left: return root
            # Zig-Zig (Left Left)
            if key < root.left.key:
                root.left.left = self.splay(root.left.left, key)
                root = self.right_rotate(root)
            # Zig-Zag (Left Right)
            elif key > root.left.key:
                root.left.right = self.splay(root.left.right, key)
                if root.left.right: root.left = self.left_rotate(root.left)
            return self.right_rotate(root) if root.left else root
        else:
            if not root.right: return root
            # Zag-Zig (Right Left)
            if key < root.right.key:
                root.right.left = self.splay(root.right.left, key)
                if root.right.left: root.right = self.right_rotate(root.right)
            # Zag-Zag (Right Right)
            elif key > root.right.key:
                root.right.right = self.splay(root.right.right, key)
                root = self.left_rotate(root)
            return self.left_rotate(root) if root.right else root

