                if (root.left.right != null) root.left = leftRotate(root.left);
            }
            return root.left != null ? rightRotate(root) : root;
        } else {
            if (root.right == null) return root;
            if (key < root.right.key) {
                root.right.left = splay(root.right.left, key);
                if (root.right.left != null) root.right = rightRotate(root.right);
            } else if (key > root.right.key) {
                root.right.right = splay(root.right.right, key);
                root = leftRotate(root);
            }
            return root.right != null ? leftRotate(root) : root;
        }
    }
}

class SplayNode {
  constructor(key) {
    this.key = key;
    this.left = null;
    this.right = null;
  }
}

class SplayTree {
  rightRotate(x) {
    const y = x.left;
    x.left = y.right;
    y.right = x;
    return y;
  }
  leftRotate(x) {
    const y = x.right;
    x.right = y.left;
    y.left = x;
    return y;
  }
  splay(root, key) {
    if (!root || root.key === key) return root;
    if (key < root.key) {
      if (!root.left) return root;
      if (key < root.left.key) {
        root.left.left = this.splay(root.left.left, key);
        root = this.rightRotate(root);
      } else if (key > root.left.key) {
        root.left.right = this.splay(root.left.right, key);
        if (root.left.right) root.left = this.leftRotate(root.left);
      }
      return root.left ? this.rightRotate(root) : root;
    } else {
      if (!root.right) return root;
      if (key < root.right.key) {
        root.right.left = this.splay(root.right.left, key);
        if (root.right.left) root.right = this.rightRotate(root.right);
      } else if (key > root.right.key) {
        root.right.right = this.splay(root.right.right, key);
        root = this.leftRotate(root);
      }
      return root.right ? this.leftRotate(root) : root;
    }
  }
}
